"use client";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import * as React from "react";
import * as AvatarPrimitive from "@radix-ui/react-avatar";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

const AvatarVariants = cva(
  "v-avatar [width:40px] [height:40px] [border-radius:50%] [object-fit:cover] [background:var(--c,var(--v-beige))] [display:inline-grid] [place-items:center] [font-size:13px] [font-weight:600] [flex:none] [color:var(--v-text)] [box-shadow:0_0_0_2px_var(--v-canvas)] [font-family:var(--font-display)] [letter-spacing:.01em]",
  {
    variants: {
      variant: {
        default: "",
        square: "-square [border-radius:14px]",
        pink: "-pink [--c:var(--v-pink)] [color:var(--v-on-accent)]",
        yellow: "-yellow [--c:var(--v-yellow)] [color:var(--v-on-accent)]",
        olive: "-olive [--c:var(--v-olive)] [color:var(--v-on-accent)]",
        blue: "-blue [--c:var(--v-blue)] [color:var(--v-on-accent)]",
        ink: "-ink [--c:var(--v-ink)] [color:var(--v-on-ink)]",
        sm: "-sm [width:28px] [height:28px] [font-size:10px]",
      },
      size: {
        default: "",
        sm: "-sm [width:28px] [height:28px] [font-size:10px]",
        lg: "-lg [width:110px] [height:110px] [font-size:34px] [letter-spacing:-.01em]",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type AvatarProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarVariants> & {
    shape?: "circle" | "rounded" | "pebble";
  };
export function Avatar({
  ref: externalMorphRef,
  className,
  variant,
  size,
  shape,
  ...props
}: AvatarProps) {
  const ownedMorphRef = useMorph<HTMLSpanElement>("controls", externalMorphRef);
  return (
    <AvatarPrimitive.Root
      ref={ownedMorphRef}
      data-slot="avatar"
      data-part="root"
      data-avatar-shape={shape}
      className={cn(AvatarVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarGroupVariants = cva(
  "v-avatar-stack [display:inline-flex] [align-items:center]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type AvatarGroupProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarGroupVariants>;
export function AvatarGroup({
  className,
  variant,
  size,
  ...props
}: AvatarGroupProps) {
  return (
    <span
      data-slot="avatar-group"
      data-part="group"
      className={cn(AvatarGroupVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarWrapperVariants = cva(
  "v-avatar-wrap [position:relative] [display:inline-block]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type AvatarWrapperProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarWrapperVariants>;
export function AvatarWrapper({
  className,
  variant,
  size,
  ...props
}: AvatarWrapperProps) {
  return (
    <span
      data-slot="avatar-wrapper"
      data-part="wrapper"
      className={cn(AvatarWrapperVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarEditVariants = cva("v-edit ", {
  variants: { variant: { default: "" }, size: { default: "" } },
  defaultVariants: { variant: "default", size: "default" },
});
export type AvatarEditProps = React.ComponentProps<"button"> &
  VariantProps<typeof AvatarEditVariants>;
export function AvatarEdit({
  className,
  variant,
  size,
  ...props
}: AvatarEditProps) {
  return (
    <Button
      type="button"
      variant="secondary"
      aria-label="Edit avatar"
      data-stable-hit=""
      data-flow="off"
      data-slot="avatar-edit"
      data-part="edit"
      className={cn(AvatarEditVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarHexVariants = cva(
  "v-hex [width:32px] [height:32px] [display:inline-grid] [place-items:center] [font-size:10px] [font-weight:700] [background:var(--c,var(--v-blue))] [clip-path:polygon(25%_6.7%,75%_6.7%,100%_50%,75%_93.3%,25%_93.3%,0_50%)] [flex:none] [color:var(--v-on-accent)] [filter:drop-shadow(0_0_0_var(--v-canvas))]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type AvatarHexProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarHexVariants>;
export function AvatarHex({
  ref: externalMorphRef,
  className,
  variant,
  size,
  ...props
}: AvatarHexProps) {
  const ownedMorphRef = useMorph<HTMLSpanElement>("controls", externalMorphRef);
  return (
    <span
      ref={ownedMorphRef}
      data-slot="avatar-hex"
      data-part="hex"
      className={cn(AvatarHexVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarHexGroupVariants = cva(
  "v-hexgroup [display:flex] [gap:0] [align-items:center]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type AvatarHexGroupProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarHexGroupVariants>;
export function AvatarHexGroup({
  className,
  variant,
  size,
  ...props
}: AvatarHexGroupProps) {
  return (
    <span
      data-slot="avatar-hex-group"
      data-part="hex-group"
      className={cn(AvatarHexGroupVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const AvatarMoreVariants = cva("v-more ", {
  variants: { variant: { default: "" }, size: { default: "" } },
  defaultVariants: { variant: "default", size: "default" },
});
export type AvatarMoreProps = React.ComponentProps<"span"> &
  VariantProps<typeof AvatarMoreVariants>;
export function AvatarMore({
  className,
  variant,
  size,
  ...props
}: AvatarMoreProps) {
  return (
    <span
      data-slot="avatar-more"
      data-part="more"
      className={cn(AvatarMoreVariants({ variant, size }), className)}
      {...props}
    />
  );
}

export type AvatarImageProps = React.ComponentProps<
  typeof AvatarPrimitive.Image
>;
export function AvatarImage({ className, ...props }: AvatarImageProps) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn("h-full w-full rounded-[inherit] object-cover", className)}
      {...props}
    />
  );
}
export type AvatarFallbackProps = React.ComponentProps<
  typeof AvatarPrimitive.Fallback
>;
export function AvatarFallback(props: AvatarFallbackProps) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      data-part="fallback"
      {...props}
    />
  );
}

@layer cojeev-states {
/* Orthogonal authored class modifiers remain composable with CVA axes. */
.v-avatar[data-avatar-shape] {
  padding: 3px;
}
.v-avatar[data-avatar-shape="circle"] {
  border-radius: 50%;
}
.v-avatar[data-avatar-shape="rounded"] {
  border-radius: 25%;
}
.v-avatar[data-avatar-shape="pebble"] {
  border-radius: 43% 57% 49% 51% / 55% 44% 56% 45%;
}
.v-avatar[data-slot].-square {
  border-radius: 14px;
}
.v-avatar[data-slot].-lg {
  width: 110px;
  height: 110px;
  font-size: 34px;
  letter-spacing: -0.01em;
}
.v-avatar[data-slot].-pink {
  --c: var(--v-pink);
  color: var(--v-on-accent);
}
.v-avatar[data-slot].-yellow {
  --c: var(--v-yellow);
  color: var(--v-on-accent);
}
.v-avatar[data-slot].-olive {
  --c: var(--v-olive);
  color: var(--v-on-accent);
}
.v-avatar[data-slot].-blue {
  --c: var(--v-blue);
  color: var(--v-on-accent);
}
.v-avatar[data-slot].-ink {
  --c: var(--v-ink);
  color: var(--v-on-ink);
}
.v-avatar[data-slot].-sm {
  width: 28px;
  height: 28px;
  font-size: 10px;
}

/* Authored contextual and pseudo-element rules, scoped to component-owned roots. */
.v-hexgroup[data-slot] .v-more {
  width: var(--hex);
  height: var(--hex);
  border-radius: 50%;
  background: var(--v-canvas);
  font-size: 9px;
  font-weight: 700;
  display: grid;
  place-items: center;
}
.v-avatar-wrap[data-slot] .v-edit {
  position: absolute;
  top: -10px;
  right: -10px;
  width: var(--edit-badge);
  height: var(--edit-badge);
  display: grid;
  place-items: center;
  color: var(--v-text);
}
.v-avatar-wrap[data-slot] .v-edit .v-shape {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.v-avatar-wrap[data-slot] .v-edit .v-icon {
  position: relative;
  width: 14px;
  height: 14px;
}
.v-avatar-wrap[data-slot] .v-edit {
  color: var(--v-on-accent);
}
.v-hexgroup[data-slot] {
  box-shadow: none;
  border: 0;
}
.v-hexgroup[data-slot] .v-more {
  box-shadow: inset 0 0 0 1px var(--v-edge);
  color: var(--v-text);
}
.v-avatar-wrap[data-slot] .v-edit {
  width: 40px;
  height: 40px;
}
.v-hexgroup[data-slot] > * + * {
  margin-left: -6px;
}
.v-hexgroup[data-slot] .v-more {
  width: 32px;
  height: 32px;
  font-size: 10px;
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: 0 0 0 2px var(--v-canvas);
}
.v-avatar-stack[data-slot] > .v-avatar + .v-avatar {
  margin-left: -10px;
}
.v-avatar-wrap[data-slot] .v-edit {
  top: -6px;
  right: -6px;
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: 0 0 0 3px var(--v-canvas);
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  cursor: pointer;
  transition:
    transform var(--t-element) var(--enter),
    background var(--t-micro);
}
.v-avatar-wrap[data-slot] .v-edit:hover {
  transform: scale(1.08) rotate(-8deg);
  background: var(--v-pink);
  color: var(--v-on-accent);
}
.v-avatar-wrap[data-slot]:has(> .v-avatar:not(.-lg)) {
  padding-right: 56px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}
.v-avatar-wrap[data-slot]:has(> .v-avatar:not(.-lg)) .v-edit {
  right: 0;
  top: 50%;
  bottom: auto;
  margin-top: -22px;
}
.v-avatar[data-slot].-square.-lg {
  border-radius: 26px;
}
.v-avatar-stack[data-slot] > .v-avatar {
  transition: transform var(--t-element) var(--enter);
}
.v-avatar-stack[data-slot]:hover > .v-avatar {
  transform: translateX(calc(var(--i, 0) * 4px));
}
.v-hexgroup[data-slot] > * {
  transition: transform var(--t-element) var(--enter);
}
.v-hexgroup[data-slot]:hover > *:hover {
  transform: translateY(-3px);
  z-index: 1;
}
.v-avatar-wrap[data-slot] .v-edit > .v-shape {
  display: none;
}
.v-avatar-wrap[data-slot] .v-edit .v-icon {
  width: 15px;
  height: 15px;
  stroke-width: 2;
}
.v-avatar-wrap[data-slot] .v-edit {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
  top: auto;
  bottom: -12px;
  right: -16px;
  background: transparent;
  color: var(--v-on-accent);
  transform: none;
  transition: none;
}
.v-avatar-wrap[data-slot] .v-edit:hover {
  transform: none;
  background: transparent;
}
.v-avatar-wrap[data-slot] .v-edit .v-icon {
  width: 19px;
  height: 19px;
}
:root[data-mode="dark"] .v-hexgroup[data-slot] .v-more {
  box-shadow: 0 0 0 2px var(--v-canvas);
}
:root[data-mode="dark"] .v-avatar[data-slot] {
  box-shadow: 0 0 0 2px var(--v-canvas);
}

/* Identity is the subject. One authored backdrop frames it; utilities stay quiet. */
.v-identity-example {
  width: 100%;
  max-width: 640px;
  margin-inline: auto;
  display: grid;
  gap: 22px;
  color: var(--v-text);
}
.v-identity-example p {
  margin: 0;
}
.v-identity-example .v-identity-example__avatar-medium {
  width: 80px;
  height: 80px;
  font-size: 26px;
}
.v-identity-example .v-avatar-wrap[data-slot][data-edit-placement="badge"] {
  padding-right: 0;
}
.v-identity-example
  .v-avatar-wrap[data-slot][data-edit-placement="badge"]
  .v-edit {
  top: auto;
  bottom: -12px;
  right: -16px;
  margin-top: 0;
}
.v-identity-example__surface {
  position: relative;
  min-width: 0;
  background: var(--v-paper);
  border: 1px solid var(--v-edge);
  border-radius: 24px;
  padding: 28px;
}
.v-identity-example__portrait {
  display: grid;
  justify-items: center;
  gap: 24px;
  text-align: center;
}
.v-identity-example__art {
  display: grid;
  place-items: center;
  min-width: 180px;
  min-height: 180px;
  padding: 28px;
  background:
    radial-gradient(ellipse at 30% 15%, var(--v-pink-soft), transparent 70%),
    var(--v-canvas);
  border-radius: 46% 54% 51% 49%/45% 48% 52% 55%;
}
.v-identity-example__eyebrow {
  display: block;
  color: var(--v-text-3);
  font-size: 11px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.v-identity-example__name {
  font-family: var(--font-display);
  font-size: clamp(22px, 3cqi, 30px);
  line-height: 1.2;
  overflow-wrap: anywhere;
}
.v-identity-example__copy {
  display: grid;
  gap: 8px;
  min-width: 0;
}
.v-identity-example__row {
  display: flex;
  align-items: center;
  gap: 24px;
}
.v-identity-example__row .v-identity-example__copy {
  flex: 1;
}
.v-identity-example__row .v-avatar-wrap {
  flex: none;
  margin-right: 12px;
}
.v-identity-example__actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}
.v-identity-example__controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: end;
  padding: 12px;
}
.v-identity-example__controls > .v-btn {
  justify-self: start;
}
.v-identity-example__detail {
  padding-top: 20px;
  margin-top: 22px;
  border-top: 1px solid var(--v-edge);
  line-height: 1.65;
}
.v-identity-example__participants {
  display: grid;
  gap: 24px;
}
.v-identity-example__participants .v-avatar-stack {
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 0;
}
.v-identity-example__participants .v-avatar-stack > .v-avatar + .v-avatar {
  margin-left: -12px;
}
.v-identity-example__roster {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--v-edge);
}
.v-identity-example__roster li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 12px;
  border-bottom: 1px solid var(--v-edge);
}
.v-identity-example__roster li > span:last-child {
  display: grid;
  gap: 3px;
  min-width: 0;
  overflow-wrap: anywhere;
}
.v-identity-example__roster small {
  color: var(--v-text-3);
}
.v-identity-example__legacy {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}
@container (max-width:440px) {
  .v-identity-example__surface {
    padding: 20px;
  }
  .v-identity-example__row {
    flex-direction: column;
    align-items: flex-start;
  }
  .v-identity-example__controls {
    grid-template-columns: 1fr;
  }
}

}
